export function canRead(record, role) {return !!roles[role] && record.access.includes(role) && !record.deleted;}
export function visibleRecords(records,role){return records.filter(r=>canRead(r,role));}
export function person(id){return people.find(p=>p.id===id)||people[0];}
export function searchRecords(records,role,query,filters={}) {
 const terms=query.toLowerCase().match(/[a-z0-9]+/g)?.filter(t=>t.length>2 && !['the','what','who','why','are','was','for','and','with','does','our','has','how','can','about','tell','show','that','this','from','which','have','work','owns','owner','when','where','please','status'].includes(t)) || [];
 const projectMention=['CI Insights','API gateway','Billing reliability','Onboarding refresh'].find(p=>query.toLowerCase().includes(p.toLowerCase()));
 return visibleRecords(records,role).filter(r=>(!projectMention||r.project===projectMention||r.title.toLowerCase().includes(projectMention.toLowerCase()))).filter(r=>(!filters.department||filters.department==='All departments'||r.department===filters.department)&&(!filters.type||filters.type==='All types'||r.type===filters.type)).map(r=>{
 const title=r.title.toLowerCase(), body=r.body.toLowerCase();const score=terms.reduce((s,t)=>s+(title.includes(t)?4:0)+(body.includes(t)?1:0),0);
 return {record:r,score};}).filter(x=>!terms.length||x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.record);
}
export function answerQuestion(records,role,query){
 const matches=searchRecords(records,role,query).slice(0,4);
 if(!matches.length) return {text:'I could not find supporting evidence in the sources available to this demo role. Try a project name, owner, or a specific decision.',sources:[],kind:'No evidence'};
 return {text:matches.slice(0,3).map((r,i)=>`${r.title}: ${r.body} [${i+1}]`).join('\n\n'),sources:matches,kind:matches.some(r=>r.status==='disputed')?'Conflicting sources':'Source-backed summary'};
}
export function createUpdate(input,role,now=new Date()){
 if(!roles[role]) throw new Error('Unknown role.');
 const clean={};for(const k of ['completed','current','upcoming','blockers','dependencies']){clean[k]=String(input[k]||'').trim();if(clean[k].length>2000)throw new Error('Each field must be 2,000 characters or fewer.');}
 if(!clean.current||!clean.completed)throw new Error('Add completed work and current work before submitting.');
 const p=person(roles[role].person); const project=['CI Insights','API gateway','Billing reliability','Onboarding refresh'].find(x=>Object.values(clean).join(' ').toLowerCase().includes(x.toLowerCase()))||'General work';
 return rec('update-'+now.getTime()+'-'+Math.random().toString(36).slice(2,6),'Update',`${p.name.split(' ')[0]}’s daily update`,Object.entries(clean).map(([k,v])=>`${({completed:'Completed',current:'Working on',upcoming:'Next',blockers:'Blocker',dependencies:'Dependency'})[k]}: ${(v||'None reported').replace(/[.!?]+$/, '')}.`).join(' '),p.department,'Dashboard',p.id,[...new Set([role,'manager','head'])],{status:'reported',date:workDate(now),project,fields:clean,evidence:'Dashboard daily pulse · employee self-report',related:project==='CI Insights'?['p1','t1']:[],history:['Submitted as a self-report.'],createdAt:now.toISOString()});
}
export function canReview(record,role){return ['manager','head'].includes(role)&&canRead(record,role)&&record.owner!==roles[role].person&&record.department===roles[role].department&&record.type==='Update'&&record.status==='reported';}
export function reviewUpdate(record,role){if(!canReview(record,role))throw new Error('Review requires a different authorized manager in this department.');return {...record,status:'verified',reviewer:roles[role].person,history:[...(record.history||[]),'Human-reviewed by '+person(roles[role].person).name+'. Review confirms the record, not independent truth of all claims.']};}
export function continuity(records,role,personId){
 const accessible=visibleRecords(records,role); const p=person(personId);const owned=accessible.filter(r=>r.owner===p.id);const deps=accessible.filter(r=>!owned.includes(r)&&r.related?.some(id=>owned.some(o=>o.id===id)));
 const checksByPerson={
 alex:[{name:'CI Insights operations',record:'doc1',gap:'Rollback drill video is missing.'},{name:'Query optimization rationale',record:'d1',gap:null},{name:'Gateway ownership',record:'d3',gap:'Primary owner is disputed.'},{name:'Customer pilot context',record:'c1',gap:null}],
 sarah:[{name:'Launch ownership',record:'t2',gap:null},{name:'Launch decision history',record:'d1',gap:null},{name:'Billing responsibilities',record:'t3',gap:null},{name:'Finance review rationale',record:'d2',gap:null}],
 noah:[{name:'Load-test responsibility',record:'m1',gap:null},{name:'Backup release procedure',record:'doc1',gap:'Rollback drill video is missing.'},{name:'Gateway handover acceptance',record:'doc4',gap:'Manager has not accepted this draft.'},{name:'Gateway ownership',record:'d3',gap:'Primary owner is disputed.'}],
 maya:[{name:'Team release policy',record:'proc1',gap:null},{name:'Architecture review context',record:'m1',gap:null},{name:'Resource allocation',record:'f1',gap:'Cross-team allocation conflict needs review.'},{name:'Ownership confirmation',record:'d3',gap:'Primary owner is disputed.'}]
 };
 const areas=checksByPerson[p.id]||[];
 const checks=areas.map((a,i)=>{const available=accessible.some(r=>r.id===a.record);return {...a,name:available?a.name:'Handover evidence check '+(i+1),gap:available?a.gap:null,available};});
 return {person:p,owned,dependencies:deps,checks,coverage:checks.length?Math.round(checks.filter(c=>c.available&&!c.gap).length/checks.length*100):0,tasks:owned.filter(r=>r.type==='Task'),decisions:accessible.filter(r=>r.type==='Decision'&&(r.owner===p.id||r.body.includes(p.name))),documents:owned.filter(r=>['Document','Process'].includes(r.type))};
}
export function handoverText(h,role){return `COMPANY BRAIN · SAMPLE HANDOVER\n${h.person.name} · ${h.person.title}\nDemo view: ${roles[role].label}\nGenerated from authorized documented sources only. Tacit knowledge and inaccessible sources are not included. All operational data is fictional.\n\nRESPONSIBILITIES\n${h.owned.map(r=>`- ${r.title} [${r.status}]\n  ${r.body}\n  Source: ${r.evidence}`).join('\n\n')}\n\nDEPENDENCIES\n${h.dependencies.map(r=>`- ${r.title}: ${r.body}\n  Source: ${r.evidence}`).join('\n')}\n\nCOVERAGE GAPS\n${h.checks.filter(c=>c.gap||!c.available).map(c=>`- ${c.name}: ${c.available?(c.gap||'Documented'):'No authorized evidence in this view.'}`).join('\n')}\n\nNEXT ACTIONS\n- Authorized manager confirms responsibilities and successor access.\n- Successor accepts handover and resolves documented gaps.\n- No external assignment or message is performed by this demo.`;}

export function canProposeHandover(role,personId,successorId='noah') {return ['manager','head'].includes(role)&&person(personId).department===roles[role].department&&personId!==successorId;}
export function auditForRole(events,role) {return events.filter(a=>a&&a.byId===roles[role]?.person);}

export function workDate(now){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now).map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}`;}
